{
  "title": "The Clockwork Rescue Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies the ruined city gates.",
      "visual_description": "Crumbled stone archways draped in faded royal banners, the city skyline jagged against a smoky sky. Mara unfolds a worn map, her brass compass catching dim light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver peers through a shattered window.",
      "visual_description": "A cracked window pane reflecting broken city lights; the Glass Diver's clear helmet and coat shimmer as he scans the interior for a path.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Mara and the Glass Diver meet at the main road.",
      "visual_description": "An overgrown square with toppled statues; Mara traces routes on her map while the Glass Diver points toward a tall cursed tower.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Oracle Lamp flickers a warning about the cursed tower.",
      "visual_description": "Inside a collapsed temple, the Oracle Lamp sits on an altar, its single flame-eye glowing as it speaks in flickering light.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scouts ahead through rubble.",
      "visual_description": "A narrow alley choked with debris; the small metal fox picks its way silently, key-wind tail ticking, blue eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the Glass Diver find the Sleeping Tax Collector.",
      "visual_description": "A half-collapsed archive room; the Sleeping Tax Collector snores on a ledger-book pillow, stamped papers stuck to his sleeves like fallen leaves.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a secret entrance beneath the tower.",
      "visual_description": "A stone staircase descending into darkness; the Oracle Lamp's flame casts long shadows as it illuminates a hidden door marked with an old seal.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox disables a trap on the staircase.",
      "visual_description": "A pressure plate trigger near the stairs; the Tin Fox carefully extracts a gear from its mechanism, freezing the trap mid-swing.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The group enters the cursed tower's ground floor.",
      "visual_description": "A circular chamber with broken mosaic floor and eerie phosphorescent moss; armored patrols of clockwork constructs stand inert but ready.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector wakes briefly to read a coded wall.",
      "visual_description": "A wall covered in faded numerical inscriptions; the Sleeping Tax Collector squints, then points a sleepy finger at a hidden lever before dozing again.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara maps a safe path through the tower's upper levels.",
      "visual_description": "A spiral staircase lined with ornate lanterns; Mara marks the map as she notes groaning floorboards and shift ing walls.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver swims through a magic mirror door.",
      "visual_description": "A tall mirror with rippling surface; the Glass Diver steps into it and emerges on the other side into a dusty treasure room, coat reflecting the glow.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp warns of a collapsing floor ahead.",
      "visual_description": "A grand hall with a chandelier overhead; cracks spider across the floor as the Oracle Lamp's flame dims and brightens urgently.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The Tin Fox triggers a hidden bridge mechanism.",
      "visual_description": "A narrow chasm in the tower; the Tin Fox's small claws turn a rusted crank, extending a stone bridge from the opposite wall.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The group reaches the tower's top and finds the escape route.",
      "visual_description": "An open balcony overlooking the ruined city; a long bridge stretches to the outer wall, partially collapsed and guarded by more clockwork patrols.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver distracts the patrols with mirror reflections.",
      "visual_description": "The Glass Diver angles his helmet to flash blinding light into the patrols' sensors, sending them clanking into each other.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Mara leads a careful crossing of the crumbling bridge.",
      "visual_description": "A rope bridge missing planks; Mara tests each step, the Tin Fox scampering ahead, while the Sleeping Tax Collector is dragged along half-asleep.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge into the outskirts.",
      "visual_description": "The far side of the bridge crumbles behind them; the ruined city recedes in twilight, and the Oracle Lamp's flame steadies as they reach safety.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

